{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useEntryAnimation",
    "displayName": "useEntryAnimation",
    "keywords": [
      "animation",
      "entry",
      "mount",
      "transition",
      "slide",
      "fade",
      "scale",
      "motion",
      "stylex"
    ],
    "params": [
      {
        "name": "preset",
        "type": "'slideDown' | 'slideUp' | 'fadeIn' | 'scaleIn'",
        "description": "Animation preset to apply on mount.",
        "default": "'slideDown'",
        "required": false
      }
    ],
    "returns": [
      {
        "name": "entryStyle",
        "type": "StyleXStyles | null",
        "description": "A StyleX style object for the entry animation, or null if the element was rendered on initial page load or hydrated from server HTML (no animation needed)."
      }
    ],
    "usage": {
      "description": "Returns a StyleX style for animating an element on mount. Only animates when the element is dynamically inserted after the initial page paint; elements rendered on page load are not animated. Uses Astryx motion tokens (duration, easing) for consistent animation timing. Server-rendered elements hydrate without the entry style and never animate; elements mounted after hydration animate.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use for conditionally rendered elements like validation messages, toasts, or expanding sections."
        },
        {
          "guidance": true,
          "description": "Spread the returned style into stylex.props() alongside other styles."
        },
        {
          "guidance": false,
          "description": "Use for elements that should be visible on initial page load; they will not animate."
        }
      ]
    },
    "relatedComponents": [
      "FieldStatus"
    ],
    "relatedHooks": [],
    "importPath": "@astryxdesign/core/hooks",
    "category": "motion & gestures"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
